CREATE TABLE "t03_large_scale_enterprise" (
  "id" INTEGER PRIMARY KEY,
  "source_file" TEXT,
  "source_sheet" TEXT,
  "excel_row" INTEGER,
  "serial_no" INTEGER,
  "enterprise_name" TEXT,
  "enterprise_location" TEXT,
  "enterprise_type" TEXT,
  "voltage_level_supply_kv" INTEGER,
  "transformer_capacity_kv" INTEGER,
  "annual_electricity_consumption_tenk_kwh" INTEGER,
  "annual_heat_consumption_gj" INTEGER,
  "annual_steam_consumption_ton" INTEGER,
  "heat_source" TEXT,
  "annual_gas_consumption_tenk_nm3" INTEGER,
  "has_pv" TEXT,
  "pv_capacity_mw" INTEGER,
  "has_storage" TEXT,
  "storage_capacity_mwh" TEXT,
  "contact" TEXT,
  "district_name" TEXT,
  "district_parse_status" TEXT
);
